export const KEY_MAX_LENGTH = 4;

/**
 * Derives a key from `input` that collides with nothing in `taken`, by
 * appending 2, 3, … and trimming the base so the result never exceeds
 * `KEY_MAX_LENGTH` — the same scheme `uniqueSlug` uses for addresses.
 */
export function uniqueKey(input: string, taken: Iterable<string>): string {
  const base =
    input.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, KEY_MAX_LENGTH) ||
