/**
 * Live issues still in a non-terminal status — done, canceled and archived
 * issues are not open. Drives the "no open issues" gate on completing a
 * project.
 */
export async function countOpenIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .get();
  return row?.value ?? 0;
}

